-- Import existing local data.js references into Supabase.
-- Run this once in the Supabase SQL Editor after supabase-schema.sql.
-- Existing rows with the same image/source/title are skipped.

begin;

create unique index if not exists references_unique_item
on public.references (image, (coalesce(source, '')), title);

on conflict (group_name)
do update set
  tags = (
    select array_agg(distinct tag order by tag)
    from unnest(public.tag_groups.tags || excluded.tags) as tag
  ),
  sort_order = excluded.sort_order;

update public.tag_groups
set tags = array_remove(tags, 'interior')
where group_name = 'Typology';

update public.tag_groups
set tags = array_remove(tags, 'extension')
where group_name = 'Elements';

update public.tag_groups
set tags = (
  select array_agg(distinct tag order by tag)
  from unnest(public.tag_groups.tags) as tag
)
where tags is not null;

on conflict (image, (coalesce(source, '')), title) do nothing;

commit;
